const render=()=>{const q=norm(oldInput.value),cat=oldFilter.value,sort=document.querySelector('#dict-sort')?.value||'alpha';let shown=all.filter(x=>(!q||norm(x.term+' '+x.definition+' '+x.category).includes(q))&&(!cat||x.category===cat));if(sort==='category')shown.sort((a,b)=>a.category.localeCompare(b.category,'fr')||a.term.localeCompare(b.term,'fr'));if(sort==='recent')shown=[...shown].reverse();const groups=new Map();shown.forEach(x=>{if(!groups.has(x.category))groups.set(x.category,[]);groups.get(x.category).push(x)});const esc=value=>String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');list.className='vocab-groups';list.innerHTML=shown.length?[...groups.entries()].map(([category,items],groupIndex)=>`<details class="vocab-group" data-category="${esc(category)}" ${q||cat?'open':''}><summary><span class="vocab-group-title">${esc(category)}</span><span class="vocab-group-meta">${items.length} terme${items.length>1?'s':''}</span></summary><div class="vocab-group-body">${items.map(x=>{const active=fav.includes(x.term);return `<article class="dict-card dict-card-v4" data-term="${esc(x.term)}"><div class="dict-meta"><span>${esc(x.category)}</span><button type="button" class="fav" aria-label="Ajouter ${esc(x.term)} aux favoris" aria-pressed="${active}">${active?'★':'☆'}</button></div><h3>${esc(x.term)}</h3><p>${esc(x.definition)}</p>${SRC[x.term]&&SRC[x.term].niveau==='sourcé'?'<p class="src-badge">✓ Sourcé</p>':''}<button class="dict-more" type="button">Voir la fiche →</button></article>`}).join('')}${items.length>6?`<button type="button" class="vocab-load-more" data-category="${esc(category)}">Afficher les ${items.length-6} autres termes de cette famille</button>`:''}</div></details>`).join(''):'<div class="notice">Aucun terme ne correspond à votre recherche. Essayez une autre orthographe ou choisissez « Toutes les catégories ».</div>';const visible=document.querySelector('#dict-visible-count');if(visible)visible.textContent=`${shown.length} terme${shown.length>1?'s':''} affiché${shown.length>1?'s':''}`;list.querySelectorAll('.fav').forEach(btn=>btn.addEventListener('click',e=>{e.stopPropagation();const term=btn.closest('.dict-card').dataset.term;fav=fav.includes(term)?fav.filter(x=>x!==term):[...fav,term].slice(-100);save();render()}));list.querySelectorAll('.dict-more').forEach(btn=>btn.addEventListener('click',()=>openCard(btn.closest('.dict-card').dataset.term)));const favBox=document.querySelector('#favorites-list');if(favBox)favBox.innerHTML=fav.length?fav.map(x=>`<button class="tag favorite-chip" type="button">${esc(x)}</button>`).join(''):'<span class="muted">Aucun favori enregistré sur cet appareil.</span>'};
function openCard(term){const x=all.find(v=>v.term===term);if(!x)return;const opener=document.activeElement;let modal=document.querySelector('#dict-detail');if(!modal){modal=document.createElement('div');modal.id='dict-detail';modal.className='dict-detail';modal.setAttribute('aria-hidden','true');document.body.appendChild(modal)}modal.innerHTML=`<div class="dict-detail-backdrop"></div><article class="dict-detail-panel" role="dialog" aria-modal="true" aria-labelledby="dict-detail-title"><button class="dict-detail-close" type="button" aria-label="Fermer la fiche">×</button><span class="tag"></span><h2 id="dict-detail-title"></h2><p class="dict-detail-definition"></p><div class="dict-detail-grid"><div><strong>Pourquoi ce terme compte</strong><p>Dans une encyclopédie du café, ce terme permet de relier une étape, une mesure, une sensation ou un acteur à son contexte. Sa définition doit toujours être interprétée avec la méthode et le référentiel utilisés.</p></div><div><strong>À ne pas confondre</strong><p>Un mot commercial, une espèce botanique, un cultivar, un procédé et un descripteur sensoriel ne sont pas interchangeables. Le contexte de la fiche fait partie de la définition.</p></div></div><div class="dict-sources"></div><div class="dict-source-line">Fiche éditoriale Café Bénin · ${new Date().getFullYear()}</div></article>`;const panel=modal.querySelector('.dict-detail-panel');panel.querySelector('.tag').textContent=x.category;panel.querySelector('#dict-detail-title').textContent=x.term;panel.querySelector('.dict-detail-definition').textContent=x.definition;const sb=panel.querySelector('.dict-sources'),info=SRC[x.term];if(info&&Array.isArray(info.sources)&&info.sources.length){const h=document.createElement('strong');h.textContent='Sources et fiabilité';const lv=document.createElement('p');lv.textContent='Niveau : '+info.niveau+' · vérifié le '+info.verifie;const nt=document.createElement('p');nt.textContent=info.note||'';const ul=document.createElement('ul');info.sources.forEach(r=>{const li=document.createElement('li'),a=document.createElement('a');a.href=r.url;a.textContent=r.titre;a.rel='noopener';a.target='_blank';li.appendChild(a);ul.appendChild(li)});sb.append(h,lv,nt,ul)}else{const h=document.createElement('strong');h.textContent='Sources et fiabilité';const p=document.createElement('p');p.textContent='Niveau : éditorial. Aucune source n’est encore rattachée à cette fiche ; la définition reste à vérifier.';sb.append(h,p)}modal.classList.add('open');modal.setAttribute('aria-hidden','false');const close=()=>{modal.classList.remove('open');modal.setAttribute('aria-hidden','true');opener?.focus()};const closeButton=modal.querySelector('.dict-detail-close');closeButton.onclick=close;modal.querySelector('.dict-detail-backdrop').onclick=close;closeButton.focus();const onKeyDown=e=>{if(e.key==='Escape'){close();document.removeEventListener('keydown',onKeyDown);return}if(e.key!=='Tab')return;const focusables=[...modal.querySelectorAll('button,a[href],input,select,textarea,[tabindex]:not([tabindex="-1"])')];if(!focusables.length)return;const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}};document.addEventListener('keydown',onKeyDown)}
